document.addEventListener("DOMContentLoaded",()=>{async function handleFormSubmit(t){t.preventDefault(),t.stopPropagation();const e={},o=[];document.querySelectorAll(".card-body").forEach(t=>{t.querySelectorAll("input, select, textarea").forEach(t=>{"INPUT"===t.tagName?"checkbox"===t.type?e[t.name]=t.checked:"file"===t.type?t.files.length>0&&o.push(new Promise((o,n)=>{const r=new FileReader;r.onload=n=>{e[t.name]=n.target.result,o()},r.onerror=n,r.readAsDataURL(t.files[0])})):e[t.name]=t.value:"TEXTAREA"===t.tagName?e[t.name]=t.value:"SELECT"===t.tagName&&(t.multiple?e[t.name]=Array.from(t.selectedOptions).map(t=>t.value):e[t.name]=-1===t.selectedIndex?null:t.options[t.selectedIndex].value)})});try{await Promise.all(o);const t=document.getElementById("trapezesId").value,n=document.querySelector('meta[name="csrf-token"]')?.content||"",r=await fetch(`/api/trapezes/update/${t}`,{method:"POST",headers:{"Content-Type":"application/json","CSRF-Token":n},credentials:"include",body:JSON.stringify(e)});if(r.redirected&&r.url)return void(window.location.href=r.url);if(r.status>=300&&r.status<400){const t=r.headers.get("Location")||r.headers.get("location");if(t){const e=t.startsWith("http")?t:new URL(t,window.location.origin).toString();return void(window.location.href=e)}throw new Error(`Redirect ${r.status} χωρίς Location header`)}if(403===r.status)throw new Error("CSRF blocked (403) — η συνεδρία έληξε ή λείπει token.");if(204===r.status)return void await Swal.fire({target:document.querySelector("main.payroll-form-layout")||document.body,heightAuto:!1,width:"min(560px, 100%)",backdrop:!1,allowOutsideClick:!1,icon:"success",title:"Επιτυχής ενημέρωση!",timer:1200,showConfirmButton:!1,customClass:{confirmButton:"class-success custom-confirm-button custom-swal-button",title:"custom-title",popup:"custom-swal-popup new-year-confirmation z-depth-5",container:"new-year-confirmation-container"}}).then(()=>window.location.href=`/companies/trapezes/edit/${t}`);if((r.headers.get("content-type")||"").includes("application/json")){const e=await r.json();if(!r.ok||!e?.success)throw new Error(`HTTP ${r.status} / success=${e?.success}`);return void await Swal.fire({target:document.querySelector("main.payroll-form-layout")||document.body,heightAuto:!1,width:"min(560px, 100%)",backdrop:!1,allowOutsideClick:!1,icon:"success",title:"Επιτυχής ενημέρωση!",timer:1200,showConfirmButton:!1,customClass:{confirmButton:"class-success custom-confirm-button custom-swal-button",title:"custom-title",popup:"custom-swal-popup new-year-confirmation z-depth-5",container:"new-year-confirmation-container"}}).then(()=>window.location.href=e.redirectUrl||`/companies/trapezes/edit/${t}`)}if(r.ok)return void await Swal.fire({target:document.querySelector("main.payroll-form-layout")||document.body,heightAuto:!1,width:"min(560px, 100%)",backdrop:!1,allowOutsideClick:!1,icon:"success",title:"Επιτυχής ενημέρωση!",timer:1200,showConfirmButton:!1,customClass:{confirmButton:"class-success custom-confirm-button custom-swal-button",title:"custom-title",popup:"custom-swal-popup new-year-confirmation z-depth-5",container:"new-year-confirmation-container"}}).then(()=>window.location.href=`/companies/trapezes/edit/${t}`);throw new Error(`HTTP error ${r.status}`)}catch(t){await Swal.fire({target:document.querySelector("main.payroll-form-layout")||document.body,heightAuto:!1,width:"min(560px, 100%)",backdrop:!1,allowOutsideClick:!1,icon:"error",title:"Αποτυχία αποθήκευσης",timer:1200,text:String(t?.message||t),showConfirmButton:!0,confirmButtonText:"Κλείσιμο",customClass:{confirmButton:"class-error custom-confirm-button custom-swal-button",title:"custom-title",popup:"custom-swal-popup new-year-confirmation z-depth-5",container:"new-year-confirmation-container"}})}}document.querySelectorAll(".submitButton").forEach(t=>{t.addEventListener("click",handleFormSubmit)})});